package com.careerpilot.modules.careerplan.service;
import com.careerpilot.modules.careerplan.dto.CareerPlanDtos.*;import com.careerpilot.modules.careerplan.taxonomy.CareerSkillTaxonomy.*;import com.careerpilot.modules.jobmatch.scoring.SkillNormalizer;import com.careerpilot.modules.profile.entity.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class CareerSkillGapService{private final SkillNormalizer normalizer;public CareerSkillGapService(SkillNormalizer normalizer){this.normalizer=normalizer;}
 public SkillGapResponse analyze(CareerDefinition definition,List<UserSkill>userSkills){Map<String,UserSkill>owned=new HashMap<>();for(UserSkill value:userSkills)owned.put(normalizer.normalize(value.getSkill().getDisplayName()),value);List<SkillGapItem>present=new ArrayList<>(),missingCore=new ArrayList<>(),missingSupporting=new ArrayList<>(),improve=new ArrayList<>();double earned=0,total=0;
  for(RequiredSkill requirement:definition.all()){double weight=requirement.category()==SkillCategory.CORE?2:1;total+=weight;UserSkill ownedSkill=owned.get(requirement.normalizedName());if(ownedSkill==null){var item=item(requirement,"MISSING",null);if(requirement.category()==SkillCategory.CORE)missingCore.add(item);else missingSupporting.add(item);continue;}var proficiency=ownedSkill.getProficiencyLevel();boolean gap=requirement.category()==SkillCategory.CORE&&proficiency==ProficiencyLevel.BEGINNER;earned+=gap?weight*.5:weight;var item=item(requirement,gap?"NEEDS_IMPROVEMENT":"PRESENT",proficiency.name());if(gap)improve.add(item);else present.add(item);}
  int score=total==0?0:(int)Math.round(earned/total*100);return new SkillGapResponse(score,List.copyOf(present),List.copyOf(missingCore),List.copyOf(missingSupporting),List.copyOf(improve));}
 private SkillGapItem item(RequiredSkill skill,String state,String proficiency){String action=state.equals("NEEDS_IMPROVEMENT")?"Practice "+skill.displayName()+" beyond beginner level and document a truthful example.":skill.nextAction();return new SkillGapItem(skill.displayName(),skill.category().name(),state,proficiency,action);}
}

